/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;public class B4progress extends B4boxes<B4progress> {	public static final String progress = "progress";	public static final String bar = "progress-bar";	public static final String strip = "progress-bar-striped";	public static final String animate = "progress-bar-animated";	public B4progress() {		super();		super.data(PageKey.type, "progress");		super.cssClass(progress);	}	public B4progress bar(int number) {		String pixels = String.valueOf((number >= 0 && number <= 100) ? number : 0) + "%";		super.box(new B4element().cssClass(bar).width(pixels).text(pixels));		return this;	}	public B4progress bar(String text, int number) {		String pixels = String.valueOf((number >= 0 && number <= 100) ? number : 0) + "%";		super.box(new B4element().cssClass(bar).width(pixels).text(text));		return this;	}	public B4progress color(String bg) {		super.box().bg(bg);		return this;	}	public B4progress strip() {		super.getContents().forEach(c -> ((B4element) c).cssClass(strip));		return this;	}	public B4progress animate() {		super.getContents().forEach(c -> ((B4element) c).cssClass(animate));		return this;	}}